import{_ as e,c as r,o,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Working with logs","description":"","frontmatter":{"title":"Working with logs"},"headers":[],"relativePath":"logs/general.md","filePath":"logs/general.md"}'),n={name:"logs/general.md"};function a(d,t,g,i,h,l){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="working-with-logs" tabindex="-1">Working with logs <a class="header-anchor" href="#working-with-logs" aria-label="Permalink to &quot;Working with logs&quot;">​</a></h1><p>The <strong>Logs</strong> tab is a single chronological journal of what happens on the page: network requests, component props and emits, <strong>Pinia</strong> changes and actions, SPA navigation and JS errors. It helps to reconstruct a scenario step by step and to hand it over as a file.</p><p>The tab is always visible, comes after <strong>Pinia Store</strong>, and works the same way in the extension and in <strong>Bookmark</strong> (<a href="/qa-tools/docs/standalone.html">Standalone</a>) mode.</p><h2 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What is logged</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td>Outgoing <strong>fetch</strong> / <strong>XMLHttpRequest</strong> call: URL, method, initiator, <strong>Params</strong>, request <strong>Headers</strong>, <strong>Authorization</strong>, request <strong>Body</strong></td></tr><tr><td><strong>Receive response</strong></td><td>Response to that call: status, duration, size, response <strong>Headers</strong>, response <strong>Body</strong>, network error</td></tr><tr><td><strong>Change props</strong></td><td>Changed props of a component: list of changes and full <strong>Before</strong> / <strong>After</strong> snapshots</td></tr><tr><td><strong>Emit</strong></td><td>Component event: component, event name, arguments, listener type (<strong>regular</strong> / <strong>once</strong>), parent chain</td></tr><tr><td><strong>Change store</strong></td><td>Changed <strong>Pinia</strong> state: list of changes and full <strong>Before</strong> / <strong>After</strong> snapshots</td></tr><tr><td><strong>Store action</strong></td><td><strong>Pinia</strong> action call: arguments, result or error, status, duration</td></tr><tr><td><strong>Navigation</strong></td><td>SPA navigation: <strong>pushState</strong>, <strong>replaceState</strong>, <strong>popstate</strong>, <strong>hashchange</strong> with <strong>From</strong> / <strong>To</strong></td></tr><tr><td><strong>JS error</strong></td><td>Uncaught error or unhandled promise rejection: message, location, stack</td></tr></tbody></table><p>Each network call produces <strong>two</strong> events. <strong>Send request</strong> stores only what was sent, <strong>Receive response</strong> stores only what came back; both keep the URL and method so the pair can be found. After a request is edited at a <a href="/qa-tools/docs/network/traffic.html">Breakpoint</a>, both events contain the data that was actually sent and received.</p><h2 id="top-toolbar" tabindex="-1">Top toolbar <a class="header-anchor" href="#top-toolbar" aria-label="Permalink to &quot;Top toolbar&quot;">​</a></h2><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>The search box filters the table. The active criteria are set in <strong>Options → Logs → Search Settings</strong> (see <a href="./settings.html">Logs settings</a>):</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>By event name</strong></td><td>Title, component, store, URL</td></tr><tr><td><strong>By key</strong></td><td>Keys in the payload and changed paths</td></tr><tr><td><strong>By value</strong></td><td>Values in the payload</td></tr></tbody></table><p>As in other tabs, a query <strong>without</strong> quotes matches a substring, a query wrapped in <strong>double quotes</strong> <code>&quot;...&quot;</code> matches exactly. The minimum query length comes from the inspector search settings (default <strong>2</strong> characters).</p><h3 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h3><p><strong>Type</strong> limits the table to the selected event types. All types are enabled by default. If every type is turned off, the table is empty and shows a hint to enable types again.</p><h3 id="status-indicators" tabindex="-1">Status indicators <a class="header-anchor" href="#status-indicators" aria-label="Permalink to &quot;Status indicators&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>N</strong> or <strong>N/M</strong></td><td>Rows after filters; with an active search or <strong>Type</strong> filter, <strong>M</strong> is the total number of events in the buffer</td></tr><tr><td><strong>ignored</strong></td><td>Number of ignored event groups. Click opens <strong>Ignored events</strong>: remove a single rule or <strong>Clear all</strong></td></tr><tr><td><strong>Paused</strong></td><td>Recording of new events is paused</td></tr></tbody></table><h3 id="log-controls" tabindex="-1">Log controls <a class="header-anchor" href="#log-controls" aria-label="Permalink to &quot;Log controls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Pause</strong> / <strong>Resume</strong></td><td>Stop and resume recording new events</td></tr><tr><td><strong>Clear</strong></td><td>Remove all recorded events</td></tr><tr><td><strong>Export Logs</strong></td><td>Export events to a file (see <a href="./export.html">Export and import</a>)</td></tr><tr><td><strong>Import Logs</strong></td><td>Open an exported <strong>JSON</strong> or <strong>HTML</strong> file</td></tr></tbody></table><h2 id="work-area" tabindex="-1">Work area <a class="header-anchor" href="#work-area" aria-label="Permalink to &quot;Work area&quot;">​</a></h2><h3 id="events-table" tabindex="-1">Events table <a class="header-anchor" href="#events-table" aria-label="Permalink to &quot;Events table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td>Checkbox</td><td>Selection for export</td></tr><tr><td><strong>Time</strong></td><td>Event time with milliseconds</td></tr><tr><td><strong>Type</strong></td><td>Colored type badge</td></tr><tr><td><strong>Event</strong></td><td>Title and short description (method and path, component and event, store and changed keys, etc.)</td></tr></tbody></table><p>Rows are highlighted by level: <strong>4xx</strong> responses — warning; <strong>5xx</strong>, network errors, failed actions and JS errors — error.</p><h3 id="selection-for-export" tabindex="-1">Selection for export <a class="header-anchor" href="#selection-for-export" aria-label="Permalink to &quot;Selection for export&quot;">​</a></h3><p>The first column contains checkboxes, in the same position as the favorites star in <strong>Props</strong> and <strong>Pinia</strong>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td>Click a checkbox</td><td>Select / unselect a row</td></tr><tr><td><strong>Shift</strong> + click</td><td>Select a range from the last clicked row</td></tr><tr><td><strong>Ctrl / Cmd</strong> + click on a row</td><td>Toggle a row without opening details</td></tr><tr><td><strong>Ctrl / Cmd</strong> + <strong>A</strong> (table focused)</td><td>Select all filtered rows</td></tr><tr><td>Header checkbox</td><td>Select all / clear selection</td></tr></tbody></table><p>When rows are selected, the button shows <strong>Export Logs (n)</strong> and exports only them. Without a selection, all filtered events are exported.</p><h3 id="event-details" tabindex="-1">Event details <a class="header-anchor" href="#event-details" aria-label="Permalink to &quot;Event details&quot;">​</a></h3><p>Clicking a row opens details on the right. The layout follows <strong>Network</strong>: a tab strip, name/value tables and <strong>JSON</strong> blocks in the selected <a href="/qa-tools/docs/options/json_mode.html">JSON mode</a>.</p><table tabindex="0"><thead><tr><th>Type</th><th>Tabs</th></tr></thead><tbody><tr><td><strong>Send request</strong></td><td><strong>Overview</strong>, <strong>Params (n)</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Receive response</strong></td><td><strong>Overview</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Change props</strong>, <strong>Change store</strong></td><td><strong>Changes (n)</strong>, <strong>Before</strong>, <strong>After</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Store action</strong></td><td><strong>Overview</strong>, <strong>Arguments</strong>, <strong>Result</strong> / <strong>Error</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Emit</strong></td><td><strong>Arguments (n)</strong>, <strong>Overview</strong>, <strong>Raw</strong></td></tr><tr><td><strong>Navigation</strong>, <strong>JS error</strong></td><td><strong>Overview</strong>, <strong>Stack</strong> (errors), <strong>Raw</strong></td></tr></tbody></table><p><strong>Changes</strong> shows a diff by path: added, removed and changed values with the old and new value. Very large diffs are truncated; the full state stays available on <strong>Before</strong> / <strong>After</strong>.</p><p>If a network body was larger than the configured event size, <strong>Body</strong> shows a notice with the original size.</p><h3 id="event-actions" tabindex="-1">Event actions <a class="header-anchor" href="#event-actions" aria-label="Permalink to &quot;Event actions&quot;">​</a></h3><p>Actions are available in the <strong>⋮</strong> menu of the details header and in the row context menu (right click or <strong>⋮</strong> in the row):</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Export event</strong></td><td>Export one event. For network events the item is <strong>Export request &amp; response</strong>: both events of the request go into one file</td></tr><tr><td><strong>Copy cURL</strong></td><td>Copy the request as a cURL command. For <strong>Receive response</strong> the command is built from its paired <strong>Send request</strong></td></tr><tr><td><strong>Open request event</strong> / <strong>Open response event</strong></td><td>Jump to the paired network event</td></tr><tr><td><strong>Ignore</strong></td><td>Stop logging this group of events</td></tr></tbody></table><p><strong>Ignore</strong> works per group: the same request (method and path), the same component, the same store, and so on. Ignored groups are not recorded at all; they can be logged again from <strong>Options → Logs → Ignore list</strong>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="when-recording-starts" tabindex="-1">When recording starts <a class="header-anchor" href="#when-recording-starts" aria-label="Permalink to &quot;When recording starts&quot;">​</a></h3><p>Recording starts together with the rest of Vue Inspector in the tab context. Events are kept in the page, so the history is available when <strong>Logs</strong> is opened later, without reloading the page.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>Every event type is a ring buffer: when it is full, the oldest events are overwritten. A shared memory budget and a maximum event size keep long sessions stable. Defaults and settings are described in <a href="./settings.html">Logs settings</a>.</p><h3 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking&quot;">​</a></h3><p>Sensitive data is masked <strong>when an event is captured</strong>, so it never reaches the view, exports or imports: passwords, tokens, cookies, authorization headers, card numbers and similar keys, as well as <strong>JWT</strong>, <strong>Bearer</strong> / <strong>Basic</strong> credentials and card numbers inside any text.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./export.html">Export and import</a></li><li><a href="./settings.html">Logs settings</a></li><li><a href="/qa-tools/docs/network/general.html">Working with requests</a></li></ul>',43)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
